import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong features based on t-statistics
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # The feats.types contains the t-statistics for each feature
        t_stat = feats.types[i]  
        if abs(t_stat) > 2.0:
            strong_features.append((fid, t_stat))

    # Sort by absolute t-statistic descending
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates (correlated features)
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Prefer the one with higher absolute t-statistic
                f1_t = next((x[1] for x in strong_features if x[0] == fid1), 0)
                f2_t = next((x[1] for x in strong_features if x[0] == fid2), 0)
                if abs(f1_t) >= abs(f2_t):
                    correlated_pairs.add(fid2)
                else:
                    correlated_pairs.add(fid1)

    # Filter out correlated features
    unique_features = [f for f in strong_features if f[0] not in correlated_pairs]

    # If no strong features, return empty design
    if not unique_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features for drivers
    drivers = tuple(f[0] for f in unique_features[:MAX_DRIVERS])

    # All features used for regression (including correlated ones that aren't drivers)
    columns = tuple(f[0] for f in unique_features)

    # Check for interaction terms (product features)
    products = []
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            # Check if correlation is high enough to suggest interaction
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]
            if abs(corr) >= 0.6:
                products.append((fid1, fid2))

    # Create loadings (weighted sum of features)
    loadings = {}
    for fid in columns:
        t_stat = next((x[1] for x in strong_features if x[0] == fid), 0)
        loadings[fid] = t_stat

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)
